sql.query:
SELECT COUNT(DISTINCT ct.MASP) AS SO_SAN_PHAM
FROM CTHD ct JOIN HOADON hd ON hd.SOHD = ct.SOHD
WHERE hd.NGHD >= '20060101' AND hd.NGHD < '20070101';

WITH SoLanMua AS (
    SELECT kh.MAKH, kh.HOTEN, COUNT(hd.SOHD) AS SO_LAN
    FROM KHACHHANG kh LEFT JOIN HOADON hd ON hd.MAKH = kh.MAKH
    GROUP BY kh.MAKH, kh.HOTEN
)
SELECT MAKH, HOTEN FROM SoLanMua WHERE SO_LAN = (SELECT MAX(SO_LAN) FROM SoLanMua) ORDER BY MAKH;

WITH TopKH AS (
    SELECT TOP (10) MAKH, HOTEN FROM KHACHHANG ORDER BY DOANHSO DESC, MAKH ASC
), SoLanMua AS (
    SELECT t.MAKH, t.HOTEN, COUNT(hd.SOHD) AS SO_LAN
    FROM TopKH t LEFT JOIN HOADON hd ON hd.MAKH = t.MAKH
    GROUP BY t.MAKH, t.HOTEN
)
SELECT MAKH, HOTEN FROM SoLanMua WHERE SO_LAN = (SELECT MAX(SO_LAN) FROM SoLanMua) ORDER BY MAKH;

