sql.query:
SELECT hv.MAHV, hv.HO + ' ' + hv.TEN AS HOTEN, hv.NGSINH, hv.MALOP
FROM LOP l JOIN HOCVIEN hv ON hv.MAHV = l.TRGLOP
ORDER BY hv.MALOP;

WITH Cuoi AS (
    SELECT k.* FROM KETQUATHI k
    WHERE k.LANTHI = (SELECT MAX(k2.LANTHI) FROM KETQUATHI k2 WHERE k2.MAHV = k.MAHV AND k2.MAMH = k.MAMH)
), Cao AS (
    SELECT MAMH, MAX(DIEM) AS DIEM_MAX FROM Cuoi GROUP BY MAMH
)
SELECT c.MAMH, hv.MAHV, hv.HO + ' ' + hv.TEN AS HOTEN, c.DIEM
FROM Cuoi c JOIN Cao ON Cao.MAMH = c.MAMH AND Cao.DIEM_MAX = c.DIEM JOIN HOCVIEN hv ON hv.MAHV = c.MAHV
ORDER BY c.MAMH, hv.MAHV;
